INSERT INTO `exceptions` (`issue_id`, `employee_id`, `course_id`, `issue_type`, `severity`, `expected_result`, `actual_result`, `detection_date`, `resolution_status`, `notes`) VALUES ('ISS-000002', 'EMP-000005', 'CRS-000001', 'BUDGET_EXCEEDED', 'CRITICAL', 'Reject course CRS-000001 ($2200.0) due to insufficient department budget in Quality Assurance.', 'Department Quality Assurance budget insufficient for cost $2200.0. Recommendation flagged/rejected.', '2026-02-16 10:15:00', 'OPEN', 'Cost exceeds remaining departmental allocation threshold.');
INSERT INTO `exceptions` (`issue_id`, `employee_id`, `course_id`, `issue_type`, `severity`, `expected_result`, `actual_result`, `detection_date`, `resolution_status`, `notes`) VALUES ('ISS-000003', 'EMP-001185', 'CRS-000466', 'DUPLICATE_COMPLETION', 'MEDIUM', 'Detect duplicate completion attempt for enrollment ENR-EMP-001185-CRS-000466 without deleting existing completion history.', 'Duplicate completion event detected for enrollment ENR-EMP-001185-CRS-000466. Handled idempotently, preserved history.', '2026-02-16 10:30:00', 'ACKNOWLEDGED', 'Secondary completion certificate generation intercepted by unique completion constraint.');
INSERT INTO `exceptions` (`issue_id`, `employee_id`, `course_id`, `issue_type`, `severity`, `expected_result`, `actual_result`, `detection_date`, `resolution_status`, `notes`) VALUES ('ISS-000004', 'EMP-002705', 'CRS-000629', 'UNASSESSED_GAP', 'HIGH', 'Keep existing employee proficiency unchanged and flag pending formal skill reassessment.', 'Course marked completed, but skill proficiency held at prior level pending reassessment.', '2026-02-16 10:45:00', 'OPEN', 'Attendance and course completion do not automatically credit proficiency increase.');
